def are_anagrams(s1: str, s2: str) -> bool:
    if len(s1) != len(s2):
        return False
    counts = {}
    for c in s1:
        counts[c] = counts.get(c, 0) + 1
    for c in s2:
        if c not in counts or counts[c] == 0:
            return False
        counts[c] -= 1
    return True

print(are_anagrams('silent', 'listen'), are_anagrams('cat', 'rat'))
